class gsl_matrix(ctypes.Structure):
    pass

class gsl_vector_complex(ctypes.Structure):
    pass

class gsl_eigen_nonsymm_workspace(ctypes.Structure):
    pass

# Define functions
def create_gsl_matrix(matrix):
    return gsl.gsl_matrix_alloc(len(matrix), len(matrix[0]))

def create_gsl_vector_complex(size):
    return gsl.gsl_vector_complex_alloc(size)

def compute_eigenvalues_nonsymm(matrix):
    # Create matrix and workspace
    gsl_matrix_ptr = create_gsl_matrix(matrix)
    workspace = gsl.gsl_eigen_nonsymm_alloc(gsl_matrix_ptr)

    # Compute eigenvalues
    gsl.gsl_eigen_nonsymm(gsl_matrix_ptr, workspace)

    # Get eigenvalues
    eigenvalues = gsl.gsl_eigen_nonsymm_vectors(gsl_matrix_ptr, workspace)

    # Free memory
    gsl.gsl_eigen_nonsymm_free(workspace)

    # Return eigenvalues as complex numbers
    return [complex(eigenvalue.real, eigenvalue.imaginary) for eigenvalue in eigenvalues]

# Function to compute eigenvalues of a non-symmetric matrix
def calculate_eigenvalues(matrix):
    eigenvalues = compute_eigenvalues_nonsymm(matrix)
    return json.dumps({"Candidate_solution": f"{eigenvalues}"})

