    try:
        coefficients = [float(c) for c in coefficients]

        gsl.gsl_poly_complex_workspace_alloc.argtypes = [ctypes.c_int]
        workspace = gsl.gsl_poly_complex_workspace_alloc(len(coefficients))

        gsl.gsl_poly_complex_solve.argtypes = [
            ctypes.POINTER(ctypes.c_double),
            ctypes.POINTER(ctypes.c_double),
            ctypes.POINTER(ctypes.c_int),
            ctypes.POINTER(GSLPolyComplexWorkspace)
        ]
        roots = (ctypes.c_double * (len(coefficients) + 1))()
        root_indices = (ctypes.c_int * len(coefficients))()
        status = gsl.gsl_poly_complex_solve(
            coefficients, roots, root_indices, workspace
        )

