            roots_list = [complex(r1, r2) for r1, r2 in zip(roots, roots[len(coefficients):])]
            return json.dumps({"Candidate_solution": roots_list})
        else:
            raise Exception(f"Error code {status}")

    except Exception as e:
        return json.dumps({"Candidate_solution": str(e)})

