import ctypes

def cblas_daxpy(N, alpha, X, Y):
    if len(X) != len(Y) or N > len(X):
        raise ValueError("Invalid input arrays.")

    gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    gslcblas.cblas_daxpy.argtypes = [ctypes.c_int, ctypes.c_double, ctypes.POINTER(ctypes.c_double),
                                   ctypes.POINTER(ctypes.c_double)]
    gslcblas.cblas_daxpy(N, alpha, (ctypes.c_double * len(X))(*X), (ctypes.c_double * len(Y))(*Y))

    return list(ctypes.c_double * len(Y))(*Y)

